var a=[{title:`Alege un interval de repetări`,text:`Alege un exercițiu, un număr de serii și un interval, de exemplu trei serii de 8–12 repetări. Începe cu o greutate care îți permite să ajungi la limita de jos a intervalului cu tehnică stabilă și câteva repetări în rezervă. Intervalul nu trebuie să fie 8–12. Limitele le stabilesc obiectivul și exercițiul.`},{title:`Câștigă creșterea sarcinii`,text:`Mai întâi, fă mai multe repetări bune cu aceeași greutate pe parcursul mai multor sesiuni. Când fiecare serie ajunge la limita de sus a intervalului, la efortul planificat, adaugă cel mai mic pas de greutate pe care îl ai. Repetările tale vor scădea de obicei din nou spre limita de jos, iar ciclul reîncepe.`},{title:`Exemplu`,text:`Săptămâna 1: ramat cu ganteră de 12 kg, 10, 9, 8. Săptămâna 2: 11, 10, 9. Săptămâna 3: 12, 12, 12 cu control stabil. Săptămâna 4: încearcă 14 kg pentru 9, 8, 8, dacă poți face acest salt cu formă bună. Aceste cifre arată cum poate decurge. Nu trebuie să te îmbunătățești în fiecare săptămână.`},{title:`Când adaptezi regula`,text:`Un salt mare de greutate poate fi prea greu, mai ales pentru mușchii mici sau cu echipament limitat de acasă. În acest caz, rămâi la sarcina actuală, adaugă repetări în total sau alege o variantă intermediară. Dacă o sesiune pare neobișnuit de obositoare, repetă ultima țintă și lasă progresia pentru mai târziu. Progresul real urcă și coboară adesea.`},{title:`Folosirea TrainUp`,text:`Planul tău dă fiecărui exercițiu serii și o țintă de repetări, iar în timpul unui antrenament notezi repetările pe care le termini la fiecare serie. TrainUp nu prescrie greutăți, așa că tu decizi când adaugi sarcină. Când ajungi la limita de sus a intervalului la fiecare serie, verifică-ți RPE și tehnica înainte să treci la o greutate mai mare.`}];var t=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: bazele siguranței și ale antrenamentului de forță`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Mayo Clinic: tehnica antrenamentului cu greutăți (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var r={sections:a,sources:t};export{r as default,a as sections,t as sources};